    ash_val = num(pd.Series([comp[7]])).iloc[0] if pd.notna(comp[7]) else np.nan
    for p in ["CO", "NOx", "SO2", "VOC", "PM25", "PM10", "BC", "OC"]:
        v = row.get({"PM25": "PM25", "PM10": "PM10"}.get(p, p))
        if v == "CAP":
            if cap_mw is None:
                out[p] = None; mode[p] = "unavailable"
                notes.append(f"{p}:电力生产NOx需装机容量，缺失")
            else:
                mw = cap_mw * 10.0
                out[p] = 8.96 if mw <= 100 else (8.19 if mw < 300 else 7.21)
                mode[p] = "capacity"
                notes.append(f"{p}:装机容量{mw:.0f}MW→NOx系数{out[p]}")
        elif v == "MB":
            mode[p] = "material_balance"
            if p == "SO2":
                if pd.isna(s_val):
                    out[p] = None; notes.append("SO2:收到基硫分缺失，无法物料衡算")
                else:
                    out[p] = 2.0 * s_val * (1 - SR)
                    notes.append(f"SO2:物料衡算 2×{s_val}×(1-{SR})={out[p]:.4f}")
            else:
                if tech_std not in COAL_PARAM:
                    out[p] = None; notes.append(f"{p}:技术{tech_std}无表C.1-C.3参数")
                elif pd.isna(ash_val):
                    out[p] = None; notes.append(f"{p}:收到基灰分缺失，无法物料衡算")
                else:
                    cp = COAL_PARAM[tech_std]
                    if p == "PM25":
                        out[p] = ash_val * (1 - cp["ar"]) * cp["fpm25"]
                    elif p == "PM10":
                        out[p] = ash_val * (1 - cp["ar"]) * cp["fpm10"]
                    elif p == "BC":
                        pm25 = ash_val * (1 - cp["ar"]) * cp["fpm25"]
                        out[p] = pm25 * cp["fbc"]
                    elif p == "OC":
                        pm25 = ash_val * (1 - cp["ar"]) * cp["fpm25"]
                        out[p] = pm25 * cp["foc"]
                    notes.append(f"{p}:物料衡算 Aar={ash_val} ar={cp['ar']}")
        else:
            out[p] = v
            mode[p] = "table_default"
    return out, mode, notes"}

